head.script:
scwin.onpageload = function() {

};

scwin.openPopup = function(id, url) {
    var options = {
        id: id
        , type: "pageFrame"
        , width: "800px"
        , height: "600px"
        , modal: true
    };
    $p.openPopup(url, options);
}

scwin.trigger1_onclick = function(e) {
    var url = "WAEA_21" + ".xml";
    scwin.openPopup("popup1", url);
};
scwin.trigger2_onclick = function(e) {
    var url = "WAEA_21_tabControl" + ".xml";
    scwin.openPopup("popup2", url);
};
scwin.trigger3_onclick = function(e) {
    var url = "WAEA_21_windowContainer" + ".xml";
    scwin.openPopup("popup3", url);
};
